function createDefaultUnlockedMap() {
	const map = {};
	[
		6,
		7,
		8,
		9
	].forEach((g) => {
		for (let p = 1; p <= 29; p++) {
			const key = `k${g}-tiet-${p}`;
			map[key] = {
				1: false,
				2: false,
				3: false,
				4: false
			};
		}
	});
	return map;
}
